INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(41272, 0, 0, 0, 0, 0, 0, 0, 0, 'Welcome back, darling! And you brought me the hides! Aren\'t you just a dear. Why, we\'ll have these cleaned, tanned, optically whitened, and attached in no time! Well, relatively speaking of course. You can\'t rush couture after all.$B$BI suppose I owe you your supplier\'s fee. And if you happen to see Ralph, do let him know to expect a shipment. I would check back with him sooner rather than later- the early bird sets the trend, you know.', 0),
(50000, 0, 0, 0, 0, 0, 0, 0, 0, 'Great! A student! Listen to me carefully...', 0),
(50002, 0, 0, 0, 0, 0, 0, 0, 0, 'You have done well, his head is in perfect conditions. Come closer and I will show you how to disguise as a filthy human.$B$BDon\'t forget your class notes!', 0),
(60117, 0, 0, 0, 0, 0, 0, 0, 0, '<The Deathguard looks you over approvingly.>$B$BYes, yes you\'ll do. Come here $C.', 0),
(80755, 273, 0, 0, 0, 0, 0, 0, 0, 'I will now grant you the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.$B$BNow, go. Gather your beasts and turn them to the cause of the Dark Lady.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(41272, 0, 0, 'You know, orange is the new purple this season. Have you considered updating your wardrobe, darling?', 0),
(50002, 0, 0, 'Come on! Bring me his head, I don\'t have all day.', 0);
